Definition ref_reserved : list (Z * Z) := rband hceil :: [(0x10000, 0x1a000); (0x2a000, 0x50000); (0x7a000, 0x6000); (0x80000, 0x34000)].

Lemma reservedZ_ref : rband hceil :: reservedZ rsegs = ref_reserved.
Proof. try hcb. unfold ref_reserved. f_equal. all: vm_compute; reflexivity. Qed.

