Lemma ref_find_segment_none : forall z n, 1 <= n -> (z + n <= 0x10000 \/ 0xb4000 <= z) ->
  find_segment rsegs z n = None.
Proof. try hcb.
  intros z n Hn Hz. unfold rsegs, RefMemImage.Ref.loaded_segments, Plain.M.loaded_segments, Plain.Plain_loaded_segments. cbn [find_segment].
  replace (Z.of_N (seg_base Plain.Plain_segment_000)) with 65536%Z by (vm_compute; reflexivity).
  replace (Z.of_N (seg_size Plain.Plain_segment_000)) with 106496%Z by (vm_compute; reflexivity).
  replace (Z.of_N (seg_base Plain.Plain_segment_001)) with 172032%Z by (vm_compute; reflexivity).
  replace (Z.of_N (seg_size Plain.Plain_segment_001)) with 327680%Z by (vm_compute; reflexivity).
  replace (Z.of_N (seg_base Plain.Plain_segment_002)) with 499712%Z by (vm_compute; reflexivity).
  replace (Z.of_N (seg_size Plain.Plain_segment_002)) with 24576%Z by (vm_compute; reflexivity).
  replace (Z.of_N (seg_base Plain.Plain_segment_003)) with 524288%Z by (vm_compute; reflexivity).
  replace (Z.of_N (seg_size Plain.Plain_segment_003)) with 212992%Z by (vm_compute; reflexivity).
  destruct (Z.leb_spec0 65536 z); destruct (Z.leb_spec0 (z + n) (65536 + 106496)); cbn [andb]; try lia.
  all: destruct (Z.leb_spec0 172032 z); destruct (Z.leb_spec0 (z + n) (172032 + 327680)); cbn [andb]; try lia.
  all: destruct (Z.leb_spec0 499712 z); destruct (Z.leb_spec0 (z + n) (499712 + 24576)); cbn [andb]; try lia.
  all: destruct (Z.leb_spec0 524288 z); destruct (Z.leb_spec0 (z + n) (524288 + 212992)); cbn [andb]; try lia.
  all: reflexivity.
Qed.

Lemma ref_ro_addr_false : forall x : word,
  (bv_unsigned x + 1 <= 0x10000 \/ 0xb4000 <= bv_unsigned x)%Z -> ro_addr rsegs x = false.
Proof. try hcb. intros x Hx. unfold ro_addr. rewrite ref_find_segment_none by lia. reflexivity. Qed.

Lemma ref_memory_read_none : forall (x : word) n,
  (1 <= Z.of_N n)%Z -> (bv_unsigned x + Z.of_N n <= 0x10000 \/ 0xb4000 <= bv_unsigned x)%Z -> memory_read rsegs x n = None.
Proof. try hcb. intros x n Hn Hx. unfold memory_read. rewrite ref_find_segment_none by lia. reflexivity. Qed.

Lemma ref_wview_overlay : forall m (x : word),
  (bv_unsigned x + 1 <= 0x10000 \/ 0xb4000 <= bv_unsigned x)%Z -> wview rsegs m x = m x.
Proof. try hcb.
  intros m x Hx. unfold wview. destruct (m x); [reflexivity|]. rewrite ref_find_segment_none by lia. reflexivity.
Qed.

Lemma ref_seg_rom_none : forall (x : word),
  (bv_unsigned x + 1 <= 0x10000 \/ 0xb4000 <= bv_unsigned x)%Z -> seg_rom rsegs x = None.
Proof. try hcb. intros x Hx. unfold seg_rom. rewrite ref_memory_read_none by (cbn; lia). reflexivity. Qed.

Lemma ref_mrd_overlay : forall m (x : word),
  (bv_unsigned x + 1 <= 0x10000 \/ 0xb4000 <= bv_unsigned x)%Z -> mrd rsegs m x = m x.
Proof. try hcb. intros m x Hx. unfold mrd. destruct (m x); [reflexivity|]. apply ref_seg_rom_none. exact Hx. Qed.

